// CV files in a PRIVATE S3 bucket (owner: Laila).
// - The bucket blocks all public access; files are encrypted at rest (SSE-S3, AES-256).
// - The object key is generated by the server (cvs/<userId>/<random>.pdf), never the
//   user's file name, so a crafted name like "../../x" cannot pick the location.
// - Downloads use a pre-signed URL that expires after 5 minutes and is only handed out
//   after the backend has checked the caller is allowed to see that CV.
const { randomUUID } = require('crypto');
const { S3Client, PutObjectCommand, DeleteObjectCommand, GetObjectCommand } = require('@aws-sdk/client-s3');
const { getSignedUrl } = require('@aws-sdk/s3-request-presigner');

const BUCKET = () => process.env.CV_BUCKET || 'ats-cv-bucket';
const s3 = new S3Client({ forcePathStyle: true });
// On Floci the Lambda reaches S3 at http://floci:4566, but the browser needs
// http://localhost:4566, so pre-signed links are built with the public address.
const presignS3 = process.env.S3_PUBLIC_ENDPOINT
  ? new S3Client({ forcePathStyle: true, endpoint: process.env.S3_PUBLIC_ENDPOINT })
  : s3;

const MAX_BYTES = 2 * 1024 * 1024;
const TYPES = {
  pdf: { mime: 'application/pdf', check: (b) => b.subarray(0, 5).toString('latin1') === '%PDF-' },
  docx: {
    mime: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    // A .docx is a ZIP file (starts with "PK\x03\x04") that contains word/document.xml
    check: (b) => b[0] === 0x50 && b[1] === 0x4b && b[2] === 0x03 && b[3] === 0x04 && b.includes('word/document.xml')
  }
};

// Validates the REAL file content, not just the name the user typed.
function inspect(fileName, contentType, buffer) {
  const ext = (fileName.split('.').pop() || '').toLowerCase();
  const type = TYPES[ext];
  if (!type) return { error: { status: 415, message: 'Only PDF or DOCX files are accepted.' } };
  if (contentType !== type.mime) return { error: { status: 415, message: 'The content type does not match the file extension.' } };
  if (buffer.length === 0) return { error: { status: 400, message: 'The file is empty.' } };
  if (buffer.length > MAX_BYTES) return { error: { status: 413, message: 'The CV must be 2 MB or smaller.' } };
  if (!type.check(buffer)) return { error: { status: 415, message: `The file content is not a real ${ext.toUpperCase()} file.` } };
  return { ext, mime: type.mime };
}

async function save(userId, buffer, ext, mime) {
  const key = `cvs/${userId}/${randomUUID()}.${ext}`;
  await s3.send(new PutObjectCommand({
    Bucket: BUCKET(),
    Key: key,
    Body: buffer,
    ContentType: mime,
    ServerSideEncryption: 'AES256',
    Metadata: { owner: userId }
  }));
  return key;
}

async function remove(key) {
  await s3.send(new DeleteObjectCommand({ Bucket: BUCKET(), Key: key }));
}

async function downloadUrl(cv) {
  return getSignedUrl(presignS3, new GetObjectCommand({
    Bucket: BUCKET(),
    Key: cv.key,
    ResponseContentDisposition: `attachment; filename="${cv.fileName.replace(/[^\w.\- ]/g, '_')}"`,
    ResponseContentType: cv.contentType
  }), { expiresIn: 300 });
}

module.exports = { inspect, save, remove, downloadUrl, MAX_BYTES };
